import os
import sys
import pandas as pd
import lightgbm as lgb
from sklearn.model_selection import train_test_split

# ---------------------------------------------------------
# Load aggregated dataset (LineSnapshots CSV)
# ---------------------------------------------------------
# Load the dataset generated by your DataPipeline

print("I AM LOADING")

aggregated_data = sys.argv[1]

data_folder = os.path.join(
    os.getcwd(),
    
    aggregated_data
)

feature_file = os.path.join(
    data_folder,
    "line_features.csv"
)


print(f"cwd      = {os.getcwd()}")
print(f"argv[0]  = {sys.argv[0]}")

for i, arg in enumerate(sys.argv):
    print(f"argv[{i}] = {arg}")

print(f"Loading features from {feature_file}")


if not os.path.exists(feature_file):
    try:
        feature_file = os.path.join(
            os.getcwd(), 
            sys.argv[2],
            "line_features.csv"
            )
        print(f"Loading features from second {feature_file}")
    except IndexError:
        raise FileNotFoundError(
            f"Feature file not found: {feature_file}"
        )


print("Exists:", os.path.exists(
    r"C:\Users\mwen\AppData\Local\LondonUndergroundSimulator"
))

print("Files:")

if os.path.exists(
    r"C:\Users\mwen\AppData\Local\LondonUndergroundSimulator"
):
    print(os.listdir(
        r"C:\Users\mwen\AppData\Local\LondonUndergroundSimulator"
    ))

df = pd.read_csv(feature_file)

# ---------------------------------------------------------
# Feature columns (aligned with SimulationSnapshot)
# ---------------------------------------------------------
FEATURES = [
    # Operational metrics
    "AvgWaiting",
    "MaxWaiting",
    "AvgLoadFactor",
    "CurrentTrainCount",

    # Raw time-of-day
    "DayOfWeek",
    "Hour",
    "Minute",
    "TimeMinutes",

    # Cyclical encoding
    "HourSin",
    "HourCos",
    "MinuteSin",
    "MinuteCos",
    "DaySin",
    "DayCos",

    # Peak flags
    "IsMorningPeak",
    "IsLunchPeak",
    "IsEveningPeak",
    "IsWeekend",

    # Trend features
    "DeltaWaiting",
    "DeltaLoadFactor",

    # Simulator-derived demand multiplier
    "ExpectedDemandMultiplier"
]

TARGET = "RecommendedFrequency"

# ---------------------------------------------------------
# Prepare data
# ---------------------------------------------------------
X = df[FEATURES]
y = df[TARGET]

X_processed = X

# ---------------------------------------------------------
# Train/test split
# ---------------------------------------------------------
X_train, X_test, y_train, y_test = train_test_split(
    X_processed, y, test_size=0.2, random_state=42
)

# ---------------------------------------------------------
# LightGBM model
# ---------------------------------------------------------
train_data = lgb.Dataset(X_train, label=y_train)
valid_data = lgb.Dataset(X_test, label=y_test)

params = {
    "objective": "regression",
    "metric": "rmse",
    "learning_rate": 0.05,
    "num_leaves": 31,
    "feature_fraction": 0.9,
    "bagging_fraction": 0.8,
    "bagging_freq": 5,
    "min_data_in_leaf": 20
}

model = lgb.train(
    params,
    train_data,
    valid_sets=[train_data, valid_data],
    num_boost_round=500,
    callbacks=[
        lgb.early_stopping(50)
    ]
)
# ---------------------------------------------------------
# Save model + scaler
# ---------------------------------------------------------

# model_dir = os.path.join(
#     os.getcwd(),  
#     "TrainingOutput"
# )

# os.makedirs(model_dir, exist_ok=True)

# model_file = os.path.join(
#     model_dir,
#     "frequency_model.txt"
# )

model_dir = sys.argv[2]

os.makedirs(model_dir, exist_ok=True)

model_file = os.path.join(
    model_dir,
    "frequency_model.txt"
)

model.save_model(model_file)

print(f"Training complete. Model saved to {model_file}")
